const file=$input.first().json;
const sourceCommit=$('02 · Pin Alpha main').first().json.sha;
const candidatePath=$('01 · Select candidate').first().json.candidate_path;
const base={
  origin:'manual',
  source_commit:sourceCommit,
  candidate_path:candidatePath,
  source_ref:'HCH725/alpha-strategy-research@'+sourceCommit+'/'+candidatePath,
  source_blob_sha:file.sha||null,
  qlib_run_id:null,
  run_state:'NOT_SUBMITTED'
};
if(file.type!=='file'||typeof file.content!=='string')
  return [{json:{...base,route:'NEEDS_REVIEW',reason:'GitHub record content is not readable',market_data_ready:null,execution_path_supported:null}}];
const record=Buffer.from(file.content.replace(/\s/g,''),'base64').toString('utf8');
if(!record.startsWith('---\n'))
  return [{json:{...base,route:'NEEDS_REVIEW',reason:'GitHub record has no readable YAML frontmatter',market_data_ready:null,execution_path_supported:null}}];
const end=record.indexOf('\n---',4);
if(end<0)
  return [{json:{...base,route:'NEEDS_REVIEW',reason:'Unterminated YAML frontmatter',market_data_ready:null,execution_path_supported:null}}];
const fm=record.slice(4,end);
const field=k=>{const m=fm.match(new RegExp('^'+k+':\\s*(.*?)\\s*$','m'));return m?m[1].trim().replace(/^[\"']|[\"']$/g,''):null;};
const schema=field('schema'),hb=field('hb_ready_status');
if(schema!=='strategy-research-record-v1'||hb!=='PASS')
  return [{json:{...base,schema,hb_ready_status:hb,route:'NEEDS_REVIEW',reason:'Invalid schema or HB_READY not PASS',market_data_ready:null,execution_path_supported:null}}];

// ponytail: Keep two exact proofs; add entries only after candidate-specific evidence is verified.
const provenCandidates=[{
  candidate_path:'three-down-three-up-consec-close-long-btcusdt-1h-2026-10-07.md',
  source_blob_sha:'4445ce0754ec4ec47ebfe7a5245e23381dc0941b',
  execution_link_ref:'/results/_validation/alpha-three-down-three-up-fullhistory-20261014/candidate-execution-link.json',
  qlib_entrypoint_ref:'/results/_validation/alpha-three-down-three-up-fullhistory-20261014/run_backtest.entrypoint.py',
  effective_config_ref:'/results/_validation/alpha-three-down-three-up-fullhistory-20261014/effective_config.json',
  qlib_runtime_commit:'bee09f23d938b96c2c1ef82d891aa0abfa171cd0'
},{
  candidate_path:'donchian-20-10-breakout-btcusdt-1h-2026-10-06.md',
  source_blob_sha:'8a09f6e642261714ef72872b601b8f679e1f0d30',
  execution_link_ref:'/results/_validation/donchian-s01509-native-20261014/candidate-execution-link.json',
  qlib_entrypoint_ref:'/results/_validation/donchian-s01509-native-20261014/run_backtest.entrypoint.py',
  effective_config_ref:'/results/_validation/donchian-s01509-native-20261014/effective_config.json',
  qlib_runtime_commit:'bee09f23d938b96c2c1ef82d891aa0abfa171cd0'
}];
const proven=provenCandidates.find(p=>candidatePath===p.candidate_path && file.sha===p.source_blob_sha);
if(proven)
  return [{json:{
    ...base,
    schema,
    hb_ready_status:hb,
    route:'READY',
    reason:'Exact candidate has verified market data and candidate-specific Qlib research execution evidence',
    market_data_ready:true,
    execution_path_supported:true,
    execution_link_ref:proven.execution_link_ref,
    qlib_entrypoint_ref:proven.qlib_entrypoint_ref,
    effective_config_ref:proven.effective_config_ref,
    qlib_runtime_commit:proven.qlib_runtime_commit,
    mapping_scope:'exact-proven-candidates-only',
    performance_claimable:false
  }}];

return [{json:{
  ...base,
  schema,
  hb_ready_status:hb,
  route:'HOLD',
  reason:'HB_READY admission accepted; no exact verified candidate-specific Qlib execution link exists yet',
  market_data_ready:null,
  execution_path_supported:null
}}];

const ssh=$input.first().json;
const upstream=$('03 · Engineering readiness').first().json;
if(ssh.code!==0) throw new Error('Node04 SSH command failed');
let receipt;
try { receipt=JSON.parse(String(ssh.stdout||'').trim()); } catch { throw new Error('Node04 receipt is not JSON'); }
if(receipt.node04!=='PASS') throw new Error('Node04 receipt is not PASS');
if(receipt.candidate_blob_sha!==upstream.source_blob_sha) throw new Error('Node04 candidate identity mismatch');
if(!/^[a-f0-9]{32}$/.test(String(receipt.run_id||''))) throw new Error('Node04 run_id missing/invalid');
return [{json:{...upstream,qlib_run_id:receipt.run_id,run_state:'FINISHED',node04_receipt:receipt}}];

// ponytail: Verify one fixed Donchian proof. A host handler reads native files; other candidates need separate proof.
const ssh=$input.first().json;
const upstream=$('04 · Verify submit receipt').first().json;
if(ssh.code!==0) throw new Error('Node05 HOLD: SSH command failed');
let receipt;
try { receipt=JSON.parse(ssh.stdout); } catch { throw new Error('Node05 HOLD: receipt is not JSON'); }
if(!receipt || typeof receipt!=='object' || Array.isArray(receipt) || receipt.node05!=='PASS')
  throw new Error('Node05 HOLD: receipt is not PASS');
if(!/^[a-f0-9]{32}$/.test(receipt.run_id) || receipt.run_id!==upstream.qlib_run_id)
  throw new Error('Node05 HOLD: run identity mismatch');
if(receipt.candidate_path!==upstream.candidate_path || receipt.candidate_blob_sha!==upstream.source_blob_sha)
  throw new Error('Node05 HOLD: candidate identity mismatch');
if(receipt.status!=='FINISHED' || upstream.run_state!=='FINISHED')
  throw new Error('Node05 HOLD: run is not FINISHED');
for(const key of ['params_count','metrics_count','artifacts_count'])
  if(!Number.isSafeInteger(receipt[key]) || receipt[key]<=0)
    throw new Error('Node05 HOLD: missing or empty '+key);
const out='/results/_validation/n8n-node04-donchian-e2e-20261014';
if(receipt.out_dir!==out || upstream.node04_receipt?.out_dir!==out ||
   typeof receipt.experiment_id!=='string' || !/^[0-9]+$/.test(receipt.experiment_id))
  throw new Error('Node05 HOLD: native run location mismatch');
const runRef=out+'/mlruns/'+receipt.experiment_id+'/'+receipt.run_id;
const dataRoot='/results/_validation/alpha-three-down-three-up-fullhistory-20261014';
const refs={
  candidate:'https://api.github.com/repos/HCH725/alpha-strategy-research/git/blobs/'+upstream.source_blob_sha,
  provider_manifest:runRef+'/artifacts/repro/provider-manifest.json',
  provider:dataRoot+'/qlib/provider',
  data_provenance:dataRoot+'/inputs/qlib_input_manifest.json',
  effective_config:runRef+'/artifacts/repro/effective_config.json',
  entrypoint:runRef+'/artifacts/repro/run_backtest.entrypoint.py',
  mlflow_run:runRef,
  mlflow_readback:out+'/mlflow_readback.json',
  manifest:out+'/manifest.json'
};
for(const [key,ref] of Object.entries(refs))
  if(receipt.refs?.[key]!==ref) throw new Error('Node05 HOLD: evidence reference mismatch '+key);
// Each true flag covers file content, not just file existence. Execution includes the cost and period recipe.
for(const key of ['candidate','data','execution','runtime','evidence'])
  if(receipt.readable?.[key]!==true) throw new Error('Node05 HOLD: unreadable '+key+' evidence');
// The existing manifest hashes mlflow_readback.json. That readback must identify the same native run.
if(receipt.manifest_verified!==true || receipt.manifest_readback_run_id!==upstream.qlib_run_id ||
   typeof receipt.manifest_sha256!=='string' || !/^[a-f0-9]{64}$/.test(receipt.manifest_sha256))
  throw new Error('Node05 HOLD: manifest/run identity mismatch');
if(receipt.performance_claimable!==false || upstream.performance_claimable!==false)
  throw new Error('Node05 HOLD: performance claim is not allowed');
return [{json:{...upstream,node05_receipt:receipt}}];
